/**
 * PROTOTYPE FIXTURE — LAY-144. Throwaway; delete with the prototype route.
 *
 * Derived from the thirteen real cleaned recordings in Handsome-Pete
 * (`cleaned-recordings/*.csv`), so every count a variant shows is the archive's
 * real count, not an invented one. Generated, not hand-written.
 *
 * Honest about what it is:
 *  - Bucket BOUNDARIES are guesses — that is part of what this prototype asks.
 *    Wind uses AGENTS.md's Light/Medium/Heavy/Storm; point of sail uses the
 *    mockup's 70/135 degree cuts; time of day uses a placeholder fixed clock
 *    (06:00-20:00 = day), NOT sunrise/sunset.
 *  - `pct` is `SOG / POL` straight from the recording, purely so the variants
 *    have a number to aggregate. Real code must recompute Target Speed from the
 *    Race's bound Polar Version and never read the logged `POL` (ADR 0027/0028).
 *  - Sea State and Sail Configuration values are mapped from the recordings'
 *    older vocabulary onto CONTEXT.md's (`flat`->`calm`, `light-chop`->`slight`;
 *    `main+jib-1`->Sail Definition 1, and so on). ADR 0023 means the owner
 *    re-enters these by hand; this is a stand-in for that re-entry.
 *  - Countable (ADR 0025) is NOT applied. No maneuver detection exists yet, so
 *    these are all matched rows, not countable rows. The distinction is real and
 *    a variant that shows a row count should eventually say which kind it is.
 */

export const WIND_IDS = ["light", "medium", "heavy", "storm"] as const
export const POS_IDS = ["upwind", "reach", "downwind"] as const
export const SEA_IDS = ["calm", "slight", "moderate", "rough"] as const
export const TIME_IDS = ["day", "night"] as const
